const output = [];
for (const item of $input.all()) {
  const binaryKeys = Object.keys(item.binary || {});
  for (const key of binaryKeys) {
    const bin = item.binary[key];
    const isPdf = (bin.mimeType && bin.mimeType.toLowerCase() === 'application/pdf') ||
                  (bin.fileName && bin.fileName.toLowerCase().endsWith('.pdf'));
    if (isPdf) {
      output.push({
        json: {
          ...item.json,
          attachmentFileName: bin.fileName || 'invoice.pdf',
          attachmentKey: key
        },
        binary: { data: bin }
      });
    }
  }
}
// Non-PDF attachments are simply skipped (ignored) since nothing is pushed for them
return output;

const item = $input.first();
let raw = '';
try {
  const content = item.json.content;
  raw = Array.isArray(content) ? content.map(c => c.text || '').join(' ') : (item.json.completion || '');
} catch (e) {
  raw = '';
}
raw = (raw || '').trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

const trigger = $('Gmail Trigger - New Invoice Email').first().json;
const attachment = $('Extract PDF Attachments').first().json;

if (!parsed) {
  return [{
    json: {
      extractionError: true,
      rawResponse: raw,
      emailSubject: trigger.subject || '',
      emailFrom: trigger.from || '',
      attachmentFileName: attachment.attachmentFileName || '',
      processedAt: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ...parsed,
    extractionError: false,
    emailSubject: trigger.subject || '',
    emailFrom: trigger.from || '',
    attachmentFileName: attachment.attachmentFileName || '',
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const errors = [];

if (item.extractionError) errors.push('AI extraction failed - could not parse a JSON response from the model');
if (!item.invoiceNumber) errors.push('Missing invoice number');
if (!item.vendorName) errors.push('Missing vendor name');
if (item.totalAmount === undefined || item.totalAmount === null || isNaN(Number(item.totalAmount))) errors.push('Missing or invalid total amount');
if (!item.invoiceDate) errors.push('Missing invoice date');
if (!item.dueDate) errors.push('Missing due date');

return [{
  json: {
    ...item,
    isValid: errors.length === 0,
    validationErrors: errors
  }
}];

const current = $('Validate Invoice Data').first().json;
const matches = $input.all().map(i => i.json);

const isDuplicate = matches.some(m =>
  String(m.invoiceNumber || '').trim() === String(current.invoiceNumber || '').trim() &&
  String(m.vendorName || '').trim().toLowerCase() === String(current.vendorName || '').trim().toLowerCase() &&
  Number(m.totalAmount) === Number(current.totalAmount)
);

return [{
  json: {
    ...current,
    isDuplicate,
    duplicateCandidatesChecked: matches.length
  }
}];

